BASE=os.environ.get('SITE_URL') or os.environ.get('URL') or os.environ.get('CF_PAGES_URL') or DEPLOYMENT.get('public_origin') or 'https://toolnest-haris.famousduck65.chatgpt.site'
BASE=BASE.rstrip('/')
parsed=urlparse(BASE)
if parsed.scheme!='https' or not parsed.netloc or parsed.path or parsed.query or parsed.fragment or parsed.username or parsed.password or any(c in BASE for c in '<>\"\r\n'):
    raise ValueError('SITE_URL must be an HTTPS origin without a path, query or fragment.')
IS_PRODUCTION=os.environ.get('CONTEXT','production')=='production'
if os.environ.get('CF_PAGES')=='1':
    IS_PRODUCTION=IS_PRODUCTION and os.environ.get('CF_PAGES_BRANCH')==os.environ.get('PRODUCTION_BRANCH','main')
    if IS_PRODUCTION and os.environ.get('PUBLIC_LAUNCH','false').lower()=='true' and not os.environ.get('SITE_URL'):
        raise ValueError('Set SITE_URL to your stable project.pages.dev origin before a public Cloudflare build.')
PUBLIC=os.environ.get('PUBLIC_LAUNCH','false').lower()=='true' and IS_PRODUCTION
SEARCH_CONSOLE=os.environ.get('GOOGLE_SITE_VERIFICATION','').strip()
SUPPORT_EMAIL=os.environ.get('SUPPORT_EMAIL','').strip()
if PUBLIC and not re.fullmatch(r'[A-Za-z0-9.!#$%&*+/=?^_`{|}~-]+@[A-Za-z0-9](?:[A-Za-z0-9.-]*[A-Za-z0-9])?\.[A-Za-z]{2,}',SUPPORT_EMAIL):
    raise ValueError('Set a valid SUPPORT_EMAIL before enabling PUBLIC_LAUNCH.')
TOOLS=[
('word-counter','Word counter','Text','Aa','Count words, characters, sentences and reading time as you type.','Paste your draft to get a live word count. Hyphenated words count as one word when there are no surrounding spaces. Reading time uses 200 words per minute, a planning estimate rather than a measured reading speed.','A 1,000-word article takes about 5 minutes to read at 200 words per minute.','Does it save my writing?','No. Text stays in this page’s memory and is cleared when you reload.'),
('case-converter','Case converter','Text','aA','Switch between sentence case, title case, uppercase and lowercase.','Paste text and select the capitalization you need. Title case capitalizes each word; it does not apply a particular editorial style guide. Sentence case uses punctuation to find sentence boundaries.','Convert “make work simpler” to “Make Work Simpler” with title case.','Will it preserve names and acronyms?','Automatic case conversion can change proper names and acronyms. Review these after converting.'),
('duplicate-line-remover','Duplicate line remover','Text','≡','Clean up lists with duplicate removal, sorting and empty-line filtering.','Paste one item per line. Duplicate matching is case-sensitive and ignores surrounding spaces. Choose whether to remove blank lines or sort the remaining lines. The first occurrence is kept.','A list containing apple, pear and apple on separate lines becomes apple and pear.','Are uppercase and lowercase the same?','No. Apple and apple are treated as separate entries.'),
('json-formatter','JSON formatter','Developer','{}','Format, validate and minify JSON without uploading your data.','Paste JSON and select Format for readable indentation or Minify to remove unnecessary whitespace. Validation uses your browser’s JSON parser. Invalid input displays a parser message rather than changing your data.','The object {"name":"Haris","active":true} can be expanded into indented lines.','Can it process JSON with comments?','No. Standard JSON does not support comments or trailing commas. Very large numbers can lose precision in JavaScript; avoid round-tripping identifiers beyond the safe integer range.'),
('url-encoder','URL encoder & decoder','Developer','↗','Encode or decode a URL component, including spaces and special characters.','Use this tool for a query parameter value or another individual URL component. Encoding the entire address also encodes its colon and slashes. Decoding rejects malformed percent sequences.','The value hello world becomes hello%20world.','Does it decode plus signs as spaces?','No. It follows decodeURIComponent, where + remains a plus sign. Form-encoded query strings may use different rules.'),
('password-generator','Password generator','Developer','✳','Create random passwords locally with the browser’s cryptographic generator.','Choose a length from 8 to 128 and select character groups. Each selected group appears at least once. Passwords are generated using crypto.getRandomValues with rejection sampling to avoid modulo bias.','For a new account, generate a fresh long password and save it in a password manager.','Are passwords stored or sent anywhere?','No. Generated passwords stay in this page. Copying places the password on your system clipboard; clear it when appropriate.'),
('compress-image-to-size','Compress image to KB','Images','↓','Reduce a photo toward a target file size, such as 100 KB or 200 KB.','Choose a JPEG, PNG or WebP image and enter an upload limit in KB. The tool searches JPEG or WebP quality settings and, if allowed, smaller dimensions. It only offers a download when the encoded file fits the limit. Here, 1 KB means 1,024 bytes.','For a portal with a 100 KB photo limit, set the target to 100 and compare the result before submitting. Check the required format and dimensions too.','Will it create exactly the requested file size?','No. It aims for at or below the limit. Very small limits may need reduced dimensions, and image detail may be lost. If it cannot reach the limit within its search range, it says so instead of offering an oversized file.'),
('image-compressor','Image compressor','Images','▧','Export a smaller JPEG or WebP with a quality setting you control.','Select a JPEG, PNG or WebP image, choose an output format and adjust quality. The browser decodes the image and exports a new file. Smaller output is not guaranteed, especially for already compressed images.','Try WebP at 80% quality, then compare the downloaded file and its size with your original.','What happens to transparency and metadata?','JPEG fills transparent areas with white. WebP supports transparency. Canvas export typically removes original camera metadata. Animated images are not supported.'),
('image-resizer','Image resizer','Images','⤢','Set image dimensions, keep the aspect ratio and download a fresh file.','Select a JPEG, PNG or WebP image, then enter the desired pixel dimensions. Keep aspect ratio enabled to avoid stretching. Output is a static PNG and may be larger than the original file.','A 1600 × 900 image resized to 800 pixels wide becomes 800 × 450 with aspect ratio locked.','How large can my image be?','This tool limits uploads to 20 MB and decoded or output images to 25 million pixels to reduce browser memory use.'),
('percentage-calculator','Percentage calculator','Calculators','%','Find a percentage, a share of a total or a percentage change.','Select the question you want to solve and enter two numbers. Percentage change uses the original value as the denominator and is undefined when that original value is zero.','15% of 240 is 36. An increase from 80 to 100 is 25%.','Can the calculator handle negative values?','Yes. The formulas keep the sign of each value. Percentage changes involving negative starting values may need context to interpret.'),
('weighted-grade-calculator','Weighted grade calculator','Calculators','A+','Combine assignment scores using your own assessment weights.','Enter each score as a percentage and its assessment weight. Results are normalized by the total entered weight, so partial course results can be calculated. An official final grade normally requires the full course weighting.','A score of 80 weighted at 40% and 90 weighted at 60% gives 86%.','What if my weights do not add to 100%?','You will see a normalized average and a note showing the entered weight. This is not a final course grade when assessments are missing.'),
('gpa-calculator','GPA calculator','Calculators','∑','Calculate a credit-weighted GPA from your course grade points.','Enter each course’s credit hours and grade points on your institution’s scale. GPA is the sum of credits multiplied by grade points divided by total credits. This tool accepts a maximum scale between 1 and 10.','A 3-credit course at 4.0 and a 2-credit course at 3.0 give a GPA of 3.60.','Can I use this for my CGPA?','Yes, if you enter all included courses on a consistent scale. Retakes, exclusions and institutional rounding policies must be applied separately.'),
('aspect-ratio-calculator','Aspect ratio calculator','Calculators','▱','Simplify a width-to-height ratio and calculate proportional dimensions.','Enter positive integer width and height values. The calculator divides both by their greatest common divisor. Enter a new width to calculate a proportional height rounded to the nearest pixel.','1920 × 1080 simplifies to 16:9. At 1280 pixels wide, the matching height is 720.','Why can the final ratio differ slightly after resizing?','Pixel dimensions are whole numbers. Rounding a fractional calculated height can introduce a small ratio difference.')]
GUIDES=[('how-to-reduce-image-size','Smaller images, sharper results','Images','A practical way to choose dimensions, compression and file formats.',[
('Start with dimensions','An image that will display at 800 pixels wide rarely needs a 5,000-pixel source for that placement. For high-density displays, consider exporting around twice the displayed width, then compare the result at its actual display size. Use the image resizer before trying increasingly low quality settings.'),('Choose a format for the content','JPEG is useful for photographs without transparency. WebP is a flexible option for photos and transparent graphics. PNG preserves crisp edges and transparency, but can be much larger for photographs. A screenshot with small text needs a different compromise from a background photo.'),('Compare before you replace','Try a moderate quality setting first. Look at faces, gradients, small text and fine edges in the downloaded image. Check both file sizes: re-encoding can make an already optimized image larger. Keep the original until you have checked the exported result.'),('Understand the local workflow','These image tools use the browser’s canvas API. The selected image is not uploaded by the tool. The export is static, so use a different workflow for animation. Canvas exports normally discard original metadata; keep your source file if you need it.')],['image-compressor','image-resizer','aspect-ratio-calculator']),
('weighted-grades-and-gpa','Weighted grades and GPA, explained','Calculators','Two averages, two different kinds of weights.',[
('Use the right weight','A weighted assessment grade uses percentages assigned to exams, assignments and other course components. GPA uses course credit hours as weights and grade points as values. Mixing percentage marks with grade points produces a number that has no consistent meaning.'),('Calculate a weighted assessment average','Multiply each percentage score by its assessment weight, add the products, then divide by the total entered weight. For an exam score of 80 with weight 40 and a project score of 90 with weight 60, the result is (80 × 40 + 90 × 60) ÷ 100 = 86.'),('Calculate a credit-weighted GPA','Multiply each course’s grade points by its credits, add the products, and divide by total credits. Three credits at 4.0 and two credits at 3.0 produce (3 × 4 + 2 × 3) ÷ 5 = 3.60. Use the same grading scale for every row.'),('Check your institution’s rules','Retakes, pass/fail courses, transferred credits and rounding may be treated differently by each institution. The calculator performs the entered arithmetic; your institution’s published rules determine which rows should be included. A partial assessment average is not a prediction of your final grade.')],['weighted-grade-calculator','gpa-calculator','percentage-calculator'])]
GUIDES.insert(0,('compress-photo-for-upload-limit','How to fit a photo under an upload limit','Images','A file-size limit and a pixel-size requirement are two separate checks.',[
('Read the upload rules first','Before compressing, note the maximum file size, accepted formats, required pixel dimensions and whether the photo may be edited. A 100 KB JPEG requirement is different from a 100 × 100 pixel requirement. Cropping, background changes and identity-photo rules are outside this tool’s scope.'),
('Set the target in KB','The target-size tool uses 1,024 bytes per KB, so 100 KB means 102,400 bytes. A portal may instead use decimal kilobytes or round its displayed value. If a file just below 100 KB is rejected for size, try a slightly lower target such as 95 KB and check the portal’s own instructions.'),
('Preserve required dimensions','The tool first tries different encoding quality settings. With dimension reduction disabled, the original width and height are preserved. Enable dimension reduction only if the upload rules permit it. Reducing dimensions changes the image size in pixels, not just the amount of storage used.'),
('Inspect before submitting','Compression can soften faces, small lettering and fine detail. Download the result, check its format and dimensions, then inspect it at normal size. The tool will report failure if it cannot meet the requested limit within its supported search. Keep the original and do not assume that meeting a size limit guarantees a portal will accept the image.')],['compress-image-to-size','image-resizer','image-compressor']))
enrich(TOOLS,GUIDES)

def icon(t):return f'<span class="tool-icon {t[2].lower()}">{escape(t[3])}</span>'
def card(t):return f'<a class="tool-card" data-category="{t[2]}" data-search="{escape((t[1]+" "+t[4]).lower())}" href="/tools/{t[0]}/">{icon(t)}<span class="card-arrow" aria-hidden="true">↗</span><h3>{t[1]}</h3><p>{t[4]}</p><span class="card-category">{t[2]}</span></a>'
def shell(title,desc,path,body,kind='website',extra=''):
    verification=f'<meta name="google-site-verification" content="{escape(SEARCH_CONSOLE,quote=True)}">' if SEARCH_CONSOLE else ''
    url=BASE+path
    schemas=[{'@context':'https://schema.org','@type':'WebSite' if path=='/' else 'WebPage','name':'Toolnest' if path=='/' else title,'description':desc,'url':url,'@id':url+'#page'}]
    if path.startswith('/tools/') and path.strip('/').split('/')[-1] in SEO:
        schemas.append({'@context':'https://schema.org','@type':'WebApplication','name':title.split(' |')[0],'url':url,'applicationCategory':'UtilitiesApplication','operatingSystem':'Any modern browser','isAccessibleForFree':True,'browserRequirements':'Requires JavaScript'})
    if path.startswith('/guides/') and path!='/guides/':
        schemas.append({'@context':'https://schema.org','@type':'Article','headline':title.split(' |')[0],'description':desc,'mainEntityOfPage':url,'author':{'@type':'Organization','name':'Toolnest'},'publisher':{'@type':'Organization','name':'Toolnest'}})

    if path.startswith('/tools/'):
        schemas.append({'@context':'https://schema.org','@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':1,'name':'Tools','item':BASE+'/'},{'@type':'ListItem','position':2,'name':title.split(' |')[0],'item':url}]})
    return f'''<!doctype html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(title)}</title><meta name="description" content="{escape(desc)}"><meta name="robots" content="{'index,follow' if PUBLIC and path!='/404/' else 'noindex,nofollow'}"><link rel="canonical" href="{url}"><meta property="og:title" content="{escape(title)}"><meta property="og:description" content="{escape(desc)}"><meta property="og:type" content="{kind}"><meta property="og:url" content="{url}">{verification}<meta name="theme-color" content="#f8f7f3"><link rel="icon" href="/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/style.css"><script type="application/ld+json">{json.dumps(schemas).replace('</','<\\/')}</script><script src="/app.js" defer></script></head><body><a class="skip" href="#main">Skip to content</a><header class="header"><a class="brand" href="/" aria-label="Toolnest home"><span class="brand-mark">✳</span>toolnest<span class="brand-dot">.</span></a><nav aria-label="Main navigation"><a href="/#tools">All tools</a><a href="/guides/">Guides</a><a href="/tools/">Categories</a><a href="/about/">About</a></nav><a class="header-cta" href="/#tools">Find your tool <span>↗</span></a></header><main id="main">{body}</main><footer><div class="footer-top"><div><a class="brand" href="/">✳ toolnest.</a><p>A little less busywork.<br>A little more getting things done.</p></div><div><strong>Explore</strong><a href="/#tools">All tools</a><a href="/guides/">Practical guides</a></div><div><strong>The details</strong><a href="/about/">About Toolnest</a><a href="/contact/">Contact</a><a href="/privacy/">Privacy</a><a href="/terms/">Terms of use</a></div><div class="footer-note"><span class="status-dot"></span> Built for your browser<p>Free to use. No account needed.</p></div></div><div class="footer-bottom"><span>© 2026 Toolnest</span><span>Small tools. More possibilities.</span></div></footer><div id="toast" role="status" aria-live="polite"></div>{extra}</body></html>'''
def write(path,title,desc,body,extra=''):
    target=OUT/(path.strip('/')+'/index.html' if path!='/' else 'index.html');target.parent.mkdir(parents=True,exist_ok=True)
    target.write_text(shell(title,desc,path,body,extra=extra))
