def area(label,id='input',placeholder='Paste or type here…'):
    readonly=' readonly' if id=='output' else ''
    return f'<label for="{id}">{escape(label)}</label><textarea id="{id}" placeholder="{escape(placeholder,quote=True)}" spellcheck="false"{readonly}></textarea>'

def inp(label,id,value,typ='number',attrs=''):return f'<div class="field"><label for="{id}">{label}</label><input id="{id}" type="{typ}" value="{value}" {attrs}></div>'
def button(text,action,cls='button'):return f'<button class="{cls}" type="button" data-action="{action}">{text}</button>'
def output():return '<div id="result" class="result" aria-live="polite">Your result will appear here.</div>'
